            return (switch (tok) {
.Text => IfClauseTok.fromText(p.text(tok.Text)),
else => null,
});
    }

pub fn fromText(txt: []const u8) ?IfClauseTok {
            if (bun.strings.eqlComptime(txt, "if")) {
                return .@"if";
            }
            if (bun.strings.eqlComptime(txt, "else")) {
                return .@"else";
            }
            if (bun.strings.eqlComptime(txt, "elif")) {
                return .elif;
            }
            if (bun.strings.eqlComptime(txt, "then")) {
                return .then;
            }
            if (bun.strings.eqlComptime(txt, "fi")) {
                return .fi;
            }
            return null;
    }
};

