    }

pub fn deinit(self: ShellErr, allocator: Allocator) void {
            switch (self) {
.sys => {
_ = self.sys.deref();
},
.custom => {
_ = allocator.free(self.custom);
},
.invalid_arguments => {

},
.todo => {
_ = allocator.free(self.todo);
},
}
    }
};

pub const GlobalJS = struct {
    globalThis: *jsc.JSGlobalObject,

pub inline fn init(g: *jsc.JSGlobalObject) GlobalJS {
            return .{ .globalThis = g };
    }

pub inline fn allocator(self: GlobalJS) Allocator {
            return self.globalThis.bunVM().allocator;
    }

pub inline fn eventLoopCtx(self: *const GlobalJS) *jsc.VirtualMachine {
            return self.globalThis.bunVM();
    }

pub inline fn throwInvalidArguments(self: GlobalJS, comptime fmt: []const u8, args: anytype) ShellErr {
            return .{ .invalid_arguments = .{ .val = bun.handleOom(std.fmt.allocPrint(self.globalThis.bunVM().allocator, fmt, args)) } };
    }

pub inline fn throwTODO(self: GlobalJS, msg: []const u8) ShellErr {
            return .{ .todo = bun.handleOom(std.fmt.allocPrint(self.globalThis.bunVM().allocator, "{s}", .{ msg })) };
    }

pub inline fn throwError(self: GlobalJS, e: bun.sys.Error) void {
            _ = self.globalThis.throwValue(e.toJS(self.globalThis));
    }

pub inline fn handleError(self: GlobalJS, e: anytype, comptime fmt: []const u8) ShellErr {
            const str = bun.handleOom(std.fmt.allocPrint(self.globalThis.bunVM().allocator, ("{s} " ++ fmt), .{ @errorName(e) }));
            return .{ .custom = str };
    }

pub inline fn throw(self: GlobalJS, comptime fmt: []const u8, args: anytype) ShellErr {
            const str = bun.handleOom(std.fmt.allocPrint(self.globalThis.bunVM().allocator, fmt, args));
            return .{ .custom = str };
    }

pub inline fn createNullDelimitedEnvMap(self: *const GlobalJS, alloc: Allocator) !?[:null][*:0]const u8 {
            return self.globalThis.bunVM().transpiler.env.map.createNullDelimitedEnvMap(alloc);
    }

pub inline fn getAllocator(self: GlobalJS) Allocator {
            return self.globalThis.bunVM().allocator;
    }

pub inline fn enqueueTaskConcurrentWaitPid(self: GlobalJS, task: anytype) void {
            _ = self.globalThis.bunVMConcurrently().enqueueTaskConcurrent(jsc.ConcurrentTask.create(jsc.Task.init(task)));
    }

pub inline fn topLevelDir(self: *const GlobalJS) []const u8 {
            return self.globalThis.bunVM().transpiler.fs.top_level_dir;
    }

pub inline fn env(self: *const GlobalJS) *bun.DotEnv.Loader {
            return self.globalThis.bunVM().transpiler.env;
    }

pub inline fn platformEventLoop(self: *const GlobalJS) *jsc.PlatformEventLoop {
            const loop = jsc.AbstractVM(self.eventLoopCtx());
            return loop.platformEventLoop();
    }

pub inline fn actuallyThrow(self: GlobalJS, shellerr: ShellErr) void {
            _ = shellerr.throwJS(self.globalThis);
    }
};

pub const GlobalMini = struct {
    mini: *jsc.MiniEventLoop,

pub inline fn init(g: *jsc.MiniEventLoop) @This() {
