                break :redirect_file .{ .atom = redirect_file };
            }
            break :redirect_file null;
};
            return .{ .flags = redirect, .redirect = redirect_file };
    }

pub fn parse_assign(self: *Parser) !?AST.Assign {
            const old = self.current;
            _ = &old;
            switch (self.peek()) {
.Text => |txtrng| {
const start_idx = self.current;
            _ = self.expect(.Text);
            const txt = self.text(txtrng);
            const var_decl: ?AST.Assign = var_decl: {
            if (hasEqSign(txt)) |eq_idx| {
                _ = &eq_idx;
                if ((eq_idx == 0)) {
                    break :var_decl null;
                }
                const label = txt[0..eq_idx];
                if ((!isValidVarName(label))) {
                    break :var_decl null;
                }
                if ((eq_idx == (txt.len - 1))) {
                    if (self.delimits(self.peek())) {
                        _ = self.expect_delimit();
                        break :var_decl .{ .label = label, .value = .{ .simple = .{ .Text = "" } } };
                    }
                    const atom_opt = try self.parse_atom();
                    if ((atom_opt == null)) {
                        _ = try self.add_error("Expected an atom", .{});
                        return ParseError.Expected;
                    }
                    const atom = atom_opt.?;
                    break :var_decl .{ .label = label, .value = atom };
                }
                const txt_value = txt[(eq_idx + 1)..txt.len];
                if (self.delimits(self.peek())) {
                    _ = self.expect_delimit();
                    break :var_decl .{ .label = label, .value = .{ .simple = .{ .Text = txt_value } } };
                }
                const right_opt = try self.parse_atom();
                if ((right_opt == null)) {
                    _ = try self.add_error("Expected an atom", .{});
                    return ParseError.Expected;
                }
                const right = right_opt.?;
                const left: AST.Atom = .{ .simple = .{ .Text = txt_value } };
                const merged = try AST.Atom.merge(left, right, self.alloc);
                break :var_decl .{ .label = label, .value = merged };
            }
            break :var_decl null;
};
            if (var_decl) |vd| {
                _ = &vd;
                return vd;
            }
            self.current = start_idx;
            return null;
},
else => {
return null;
},
}
    }

pub fn parse_atom(self: *Parser) !?AST.Atom {
            var array_alloc = std.heap.stackFallback(@sizeOf(AST.SimpleAtom), self.alloc);
            _ = &array_alloc;
            var atoms = try std.array_list.Managed(AST.SimpleAtom).initCapacity(array_alloc.get(), 1);
            _ = &atoms;
            var has_brace_open = false;
            _ = &has_brace_open;
            var has_brace_close = false;
            _ = &has_brace_close;
            var has_comma = false;
            _ = &has_comma;
            var has_glob_syntax = false;
            _ = &has_glob_syntax;
            {
                while ((switch (self.peek()) {
.Delimit => brk: {
                _ = self.expect(.Delimit);
                break :brk false;
},
.Eof, .Semicolon, .Newline => false,
else => |t| brk: {
                if (((self.inside_subshell != null) and (self.inside_subshell.?.closing_tok() == t))) {
                    break :brk false;
                }
                break :brk true;
},
})) {
                    const next = self.peek_n(1);
                    const next_delimits = self.delimits(next);
                    const peeked = self.peek();
                    const should_break = next_delimits;
                    switch (peeked) {
.Asterisk => {
has_glob_syntax = true;
                    _ = self.expect(.Asterisk);
                    _ = try atoms.append(.asterisk);
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        break;
                    }
},
.DoubleAsterisk => {
has_glob_syntax = true;
                    _ = self.expect(.DoubleAsterisk);
                    _ = try atoms.append(.double_asterisk);
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        break;
                    }
},
.BraceBegin => {
has_brace_open = true;
                    _ = self.expect(.BraceBegin);
                    _ = try atoms.append(.brace_begin);
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        if (should_break) {
                            break;
                        }
                    }
},
.BraceEnd => {
has_brace_close = true;
                    _ = self.expect(.BraceEnd);
                    _ = try atoms.append(.brace_end);
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        break;
                    }
},
.Comma => {
has_comma = true;
                    _ = self.expect(.Comma);
                    _ = try atoms.append(.comma);
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        if (should_break) {
                            break;
                        }
                    }
},
.CmdSubstBegin => {
_ = self.expect(.CmdSubstBegin);
                    const is_quoted = self.matchTok(.CmdSubstQuoted);
                    var subparser = self.make_subparser(.cmd_subst);
                    _ = &subparser;
                    const script = (blk_catch_1: { break :blk_catch_1 ((subparser.parse_impl()) catch |e| { _ = &e; _ = self.continue_from_subparser((&subparser));
                    return e; }); });
                    _ = try atoms.append(.{ .cmd_subst = .{ .script = script, .quoted = is_quoted } });
                    _ = self.continue_from_subparser((&subparser));
                    if (self.delimits(self.peek())) {
                        _ = self.matchTok(.Delimit);
                        break;
                    }
},
.SingleQuotedText, .DoubleQuotedText, .Text => |txtrng| {
_ = self.advance();
                    var txt = self.text(txtrng);
                    _ = &txt;
                    if ((((peeked == .Text) and (txt.len > 0)) and (txt[0] == 126))) {
                        txt = txt[1..];
                        _ = try atoms.append(.tilde);
                        if ((txt.len > 0)) {
                            _ = try atoms.append(.{ .Text = txt });
                        }
                    } else {
                        if (((txt.len == 0) and ((peeked == .SingleQuotedText) or (peeked == .DoubleQuotedText)))) {
                            _ = try atoms.append(.quoted_empty);
                        } else {
                            _ = try atoms.append(.{ .Text = txt });
                        }
                    }
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        if (should_break) {
                            break;
                        }
                    }
},
.Var => |txtrng| {
_ = self.expect(.Var);
                    const txt = self.text(txtrng);
                    _ = try atoms.append(.{ .Var = txt });
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        if (should_break) {
                            break;
                        }
                    }
},
.VarArgv => |int| {
_ = self.expect(.VarArgv);
                    _ = try atoms.append(.{ .VarArgv = int });
                    if (next_delimits) {
                        _ = self.matchTok(.Delimit);
                        if (should_break) {
                            break;
                        }
                    }
},
.OpenParen, .CloseParen => {
_ = try self.add_error("Unexpected token: `{s}`", .{ (if ((peeked == .OpenParen)) "(" else ")") });
                    return ParseError.Unexpected;
},
.Pipe => {
return null;
},
.DoublePipe => {
return null;
},
.Ampersand => {
return null;
},
.DoubleAmpersand => {
return null;
},
.Redirect => {
return null;
},
.Dollar => {
return null;
},
.Eq => {
return null;
},
.Semicolon => {
return null;
},
.Newline => {
return null;
},
.CmdSubstQuoted => {
return null;
},
.CmdSubstEnd => {
return null;
},
.JSObjRef => {
return null;
},
.Delimit => {
return null;
},
.Eof => {
return null;
},
.DoubleBracketOpen => {
return null;
},
.DoubleBracketClose => {
return null;
},
}
                }
            }
            return (switch (atoms.items.len) {
0 => null,
1 => {
{
                if (bun.Environment.allow_assert) {
                    _ = assert((atoms.capacity == 1));
                }
                return AST.Atom.new_simple(atoms.items[0]);
            }
},
else => AST.Atom{ .compound = .{ .atoms = atoms.items[0..atoms.items.len], .brace_expansion_hint = ((has_brace_open and has_brace_close) and has_comma), .glob_hint = has_glob_syntax } },
});
    }

pub fn allocate(self: *const Parser, comptime T: type, val: T) !*T {
            const heap = try self.alloc.create(T);
            heap.* = val;
            return heap;
    }

pub fn text(self: *const Parser, range: Token.TextRange) []const u8 {
            return self.strpool[range.start..range.end];
    }

pub fn advance(self: *Parser) Token {
            if ((!self.is_at_end())) {
                self.current = (self.current + 1);
            }
            return self.prev();
    }

pub fn is_at_end(self: *Parser) bool {
            return ((self.peek() == .Eof) or ((self.inside_subshell != null) and (self.inside_subshell.?.closing_tok() == self.peek())));
    }

pub fn expect(self: *Parser, toktag: TokenTag) Token {
            if (bun.Environment.allow_assert) {
                _ = assert((toktag == std.meta.activeTag(self.peek())));
            }
            if (self.check(toktag)) {
                return self.advance();
            }
            _ = @panic("Unexpected token");
    }

pub fn expect_any(self: *Parser, toktags: []const TokenTag) Token {
            const peeked = self.peek();
            for (cp_iter_slice(toktags)) |toktag| {
                _ = &toktag;
                if ((toktag == std.meta.activeTag(peeked))) {
                    return self.advance();
                }
            }
            _ = @panic("Unexpected token");
    }

pub fn delimits(self: *Parser, tok: Token) bool {
            return ((((((tok == .Delimit) or (tok == .Semicolon)) or (tok == .Semicolon)) or (tok == .Eof)) or (tok == .Newline)) or ((self.inside_subshell != null) and (tok == self.inside_subshell.?.closing_tok())));
    }

pub fn expect_delimit(self: *Parser) Token {
            if (bun.Environment.allow_assert) {
                _ = assert(self.delimits(self.peek()));
            }
            if (((((self.check(.Delimit) or self.check(.Semicolon)) or self.check(.Newline)) or self.check(.Eof)) or ((self.inside_subshell != null) and self.check(self.inside_subshell.?.closing_tok())))) {
                return self.advance();
            }
            _ = @panic("Expected a delimiter token");
    }

pub fn match_if_clausetok(self: *Parser, toktag: IfClauseTok) bool {
            const tok_peek: Token = self.peek();
            if ((((tok_peek == .Text) and self.delimits(self.peek_n(1))) and bun.strings.eql(self.text(tok_peek.Text), @tagName(toktag)))) {
                _ = self.advance();
                _ = self.expect_delimit();
                return true;
            }
            return false;
    }

pub fn matchTok(self: *Parser, toktag: TokenTag) bool {
            if ((std.meta.activeTag(self.peek()) == toktag)) {
                _ = self.advance();
                return true;
            }
            return false;
    }

pub fn match_any_comptime(self: *Parser, comptime toktags: []const TokenTag) bool {
            const peeked = std.meta.activeTag(self.peek());
            inline for (toktags) |tag| {
                if ((peeked == tag)) {
                    _ = self.advance();
                    return true;
                }
            }
            return false;
    }

pub fn match_any(self: *Parser, toktags: []const TokenTag) bool {
