            self.heap.len = @intCast(slc.len);
},
}
    }

pub inline fn sliceMutable(self: *@This()) []T {
            return (switch (self.*) {
.inlined => {
{
                if ((self.inlined.len == 0)) {
                    return &.{};
                }
                return self.inlined.items[0..self.inlined.len];
            }
},
.heap => {
{
                if ((self.heap.len == 0)) {
                    return &.{};
                }
                return self.heap.slice();
            }
},
});
    }

pub inline fn slice(self: *const @This()) []const T {
            return (switch (self.*) {
.inlined => {
{
                if ((self.inlined.len == 0)) {
                    return &.{};
                }
                return self.inlined.items[0..self.inlined.len];
            }
},
.heap => {
{
                if ((self.heap.len == 0)) {
                    return &.{};
                }
                return self.heap.slice();
            }
},
});
    }

pub inline fn get(self: *@This(), idx: usize) *T {
            return (switch (self.*) {
.inlined => {
{
                if (bun.Environment.allow_assert) {
                    if ((idx >= self.inlined.len)) {
                        _ = @panic("Index out of bounds");
                    }
                }
                return (&self.inlined.items[@as(usize, @intCast(idx))]);
            }
},
.heap => (&self.heap.ptr[@as(usize, @intCast(idx))]),
});
    }

pub inline fn getConst(self: *const @This(), idx: usize) *const T {
            return (switch (self.*) {
.inlined => {
{
                if (bun.Environment.allow_assert) {
                    if ((idx >= self.inlined.len)) {
                        _ = @panic("Index out of bounds");
                    }
                }
                return (&self.inlined.items[@as(usize, @intCast(idx))]);
            }
},
.heap => (&self.heap.ptr[@as(usize, @intCast(idx))]),
});
    }

pub fn append(self: *@This(), val: T) void {
            switch (self.*) {
.inlined => {
if ((self.inlined.len == INLINED_MAX)) {
                const promoted = self.inlined.promote(INLINED_MAX, val);
                self.* = .{ .heap = promoted };
                return;
            }
            self.inlined.items[cp_cast_int(usize, self.inlined.len)] = val;
            self.inlined.len = (self.inlined.len + 1);
},
.heap => {
_ = bun.handleOom(self.heap.append(bun.default_allocator, val));
},
}
    }

pub fn clearRetainingCapacity(self: *@This()) void {
            switch (self.*) {
.inlined => {
self.inlined.len = 0;
},
.heap => {
_ = self.heap.clearRetainingCapacity();
},
}
    }

pub fn last(self: *@This()) ?*T {
            if ((self.len() == 0)) {
                return null;
            }
            return self.get((self.len() - 1));
    }

pub fn lastUnchecked(self: *@This()) *T {
            return self.get((self.len() - 1));
    }

pub fn lastUncheckedConst(self: *const @This()) *const T {
            return self.getConst((self.len() - 1));
    }
    const ByteList = bun.BabyList(T);
    pub const zeroes: @This() = .{ .inlined = .{} };
    pub const Inlined = struct {
        items: [INLINED_MAX]T = undefined,
        len: u32 = 0,
    
    pub fn slice(self: *const @This()) []const T {
                return self.items[0..self.len];
        }
    
    pub fn allocatedSlice(self: *const @This()) []const T {
                return (&self.items);
        }
    
    pub fn promote(self: *@This(), n: usize, val: T) bun.BabyList(T) {
                var list = bun.handleOom(bun.BabyList(T).initCapacity(bun.default_allocator, n));
                _ = &list;
                _ = bun.handleOom(list.appendSlice(bun.default_allocator, self.items[0..INLINED_MAX]));
                _ = bun.handleOom(list.append(bun.default_allocator, val));
                return list;
        }
    
    pub fn orderedRemove(self: *@This(), idx: usize) T {
                if (((self.len - 1) == idx)) {
                    return self.pop();
                }
                const slice_to_shift = self.items[(idx + 1)..self.len];
                _ = std.mem.copyForwards(T, self.items[idx..(self.len - 1)], slice_to_shift);
                self.len = (self.len - 1);
        }
    
    pub fn swapRemove(self: *@This(), idx: usize) T {
                if (((self.len - 1) == idx)) {
                    return self.pop();
                }
                const old_item = self.items[@as(usize, @intCast(idx))];
                self.items[cp_cast_int(usize, idx)] = self.pop();
                return old_item;
        }
    
    pub fn pop(self: *@This()) T {
                const ret = self.items[@as(usize, @intCast((self.len - 1)))];
                self.len = (self.len - 1);
                return ret;
        }
    };
};
